import{_ as l,a0 as o,w as n,s as p,I as e,x as r,a1 as s,A as i,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"用 InDesign 的开源替代方案 Scribus 设计书籍封面 | LCTT x X-CMD","titleTemplate":false,"description":"用 InDesign 的开源替代方案 Scribus 设计书籍封面 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 InDesign 的开源替代方案 Scribus 设计书籍封面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 InDesign 的开源替代方案 Scribus 设计书籍封面 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200902 Design a book cover with an open source alternative to InDesign","title":"用 InDesign 的开源替代方案 Scribus 设计书籍封面","tag":"202009","desc":""},"relativePath":"202009/20200902 Design a book cover with an open source alternative to InDesign.md","filePath":"[post].md"}'),b={name:"202009/20200902 Design a book cover with an open source alternative to InDesign.md"};function d(m,t,g,f,y,D){const u=o("Link");return n(),p("div",null,[t[23]||(t[23]=e("h1",{id:"用-indesign-的开源替代方案-scribus-设计书籍封面",tabindex:"-1"},[r("用 InDesign 的开源替代方案 Scribus 设计书籍封面 "),e("a",{class:"header-anchor",href:"#用-indesign-的开源替代方案-scribus-设计书籍封面","aria-label":"Permalink to “用 InDesign 的开源替代方案 Scribus 设计书籍封面”"},"​")],-1)),t[24]||(t[24]=e("blockquote",null,[e("p",null,"使用开源的出版软件 Scribus 来制作你的下一本自出版书籍的封面。")],-1)),t[25]||(t[25]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/16/213714ppvfzm6idv9nnynp.jpg",alt:""})],-1)),e("p",null,[t[2]||(t[2]=r("我最近写完了一本关于 ",-1)),s(u,{href:"https://opensource.com/article/20/8/c-programming-cheat-sheet"},{default:i(()=>[...t[0]||(t[0]=[r("C 语言编程",-1)])]),_:1}),t[3]||(t[3]=r("的书，我通过 ",-1)),s(u,{href:"https://www.lulu.com/"},{default:i(()=>[...t[1]||(t[1]=[r("Lulu.com",-1)])]),_:1}),t[4]||(t[4]=r(" 自行出版。我已经用 Lulu 做了好几个图书项目，它是一个很棒的平台。今年早些时候，Lulu 做了一些改变，让作者在创作图书封面时有了更大的控制权。以前，你只需上传一对大尺寸图片作为书的封面和封底。现在，Lulu 允许作者上传完全按照你的书的尺寸定制的 PDF。",-1))]),e("p",null,[t[6]||(t[6]=r("你可以使用 ",-1)),s(u,{href:"https://www.scribus.net/"},{default:i(()=>[...t[5]||(t[5]=[r("Scribus",-1)])]),_:1}),t[7]||(t[7]=r(" 这个开源页面布局程序来创建封面。下面是我的做法。",-1))]),t[26]||(t[26]=a('<h3 id="下载一个模板" tabindex="-1">下载一个模板 <a class="header-anchor" href="#下载一个模板" aria-label="Permalink to “下载一个模板”">​</a></h3><p>当你在 Lulu 上输入图书的信息时，最终会进入<ruby>设计<rt>Design</rt></ruby>栏。在该页面的<ruby>设计封面<rt>Design Your Cover</rt></ruby>部分，你会发现一个方便的<ruby>下载模板<rt>Download Template</rt></ruby>按钮，它为你的图书封面提供了一个 PDF 模板。</p><p><img src="https://opensource.com/sites/default/files/uploads/lulu-download-template.jpg" alt="Lulu Design your Cover page" title="Lulu Design your Cover page"></p><p>下载此模板，它为你提供了在 Scribus 中创建自己的书籍封面所需的信息。</p><p><img src="https://opensource.com/sites/default/files/uploads/lulu-pdf-template.jpg" alt="Lulu&#39;s cover template" title="Lulu&#39;s cover template"></p><p>最重要的细节是：</p><ul><li><ruby>文件总尺寸（含出血）<rt>Total Document Size (with bleed)</rt></ruby></li><li><ruby>出血区（从裁切边缘）<rt>Bleed area (from trim edge)</rt></ruby></li><li><ruby>书脊区<rt>Spine area</rt></ruby></li></ul><p><ruby>出血<rt>Bleed</rt></ruby>是一个印刷术语，在准备“印刷就绪”文件时，这个术语很重要。它与普通文件中的页边距不同。打印文件时，你会为顶部、底部和侧面设置一个页边距。在大多数文档中，页边距通常为一英寸左右。</p><p>但在印刷就绪的文件中，文档的尺寸需要比成品书大一些，因为书籍的封面通常包括颜色或图片，一直到封面的边缘。为了创建这种设计，你要使颜色或图片超出你的边距，印刷厂就会把多余的部分裁切掉，使封面缩小到准确的尺寸。因此，“裁切”就是印刷厂将封面精确地裁剪成相应尺寸。而“出血区”就是印刷厂裁掉的多余部分。</p><p>如果你没有出血区，印刷厂就很难完全按照尺寸印刷封面。如果打印机只偏离了一点点，你的封面最终会在边缘留下一个微小的、白色的、没有印刷的边缘。使用出血和修剪意味着你的封面每次都能看起来正确。</p><h3 id="在-scribus-中设置书籍的封面文档" tabindex="-1">在 Scribus 中设置书籍的封面文档 <a class="header-anchor" href="#在-scribus-中设置书籍的封面文档" aria-label="Permalink to “在 Scribus 中设置书籍的封面文档”">​</a></h3><p>要在 Scribus 中创建新文档，请从定义文档尺寸的<ruby>新文档<rt>New Document</rt></ruby>对话框开始。单击<ruby>出血<rt>Bleeds</rt></ruby>选项卡，并输入 PDF 模板所说的出血尺寸。Lulu 图书通常在所有边缘使用 0.125 英寸的出血量。</p><p>对于 Scribus 中的文档总尺寸，你不能只使用 PDF 模板上的文档总尺寸。如果这样做，你的 Scribus 文档的尺寸会出现错误。相反，你需要做一些数学计算来获取正确的尺寸。</p><p>看下 PDF 模板中的<ruby>文件总尺寸（含出血）<rt>Total Document Size (with bleed)</rt></ruby>。这是将要发送给打印机的 PDF 的总尺寸，它包括封底、书脊和封面（包含出血）。要在 Scribus 中输入正确的尺寸，你必须从所有边缘中减去出血。例如，我最新的书的尺寸是<ruby>四开本<rt>Crown Quarto</rt></ruby>，装订后尺寸为 7.44&quot; x 9.68&quot;，书脊宽度为 0.411&quot;。加上 0.125&quot; 的出血量，文件总尺寸（含出血）是 15.541&quot; × 9.93&quot;。因此，我在 Scribus 中的文档尺寸是：</p><ul><li>宽：15.541-2 541-x 541-0.125=15.291&quot;</li><li>高：9.93-2 93-x 93-0.125=9.68&quot;</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/scribus-new-document.jpg" alt="Scribus document setup" title="Scribus document setup"></p><p>这将设置一个新的适合我的书的封面尺寸的 Scribus 文档。新的 Scribus 文档尺寸应与 PDF 模板上列出的“文件总尺寸（含出血）”完全匹配。</p><h3 id="从书脊开始" tabindex="-1">从书脊开始 <a class="header-anchor" href="#从书脊开始" aria-label="Permalink to “从书脊开始”">​</a></h3><p>在 Scribus 中创建新的书籍封面时，我喜欢从书脊区域开始。这可以帮助我验证我是否在 Scribus 中正确定义了文档。</p><p>使用<ruby>矩形<rt>Rectangle</rt></ruby>工具在文档上绘制一个彩色方框，书脊需要出现在那里。你不必完全按照正确的尺寸和位置来绘制，只要大小差不多并使用<ruby>属性<rt>Properties</rt></ruby>来设置正确的值即可。在形状的属性中，选择左上角基点，然后输入书脊需要放在的 x、y 位置和尺寸。同样，你需要做一些数学计算，并使用 PDF 模板上的尺寸作为参考。</p><p><img src="https://opensource.com/sites/default/files/uploads/scribus-empty-document.jpg" alt="Empty Scribus document" title="Empty Scribus document"></p><p>例如，我的书的修边尺寸是 7.44&quot;×9.68&quot;，这是印刷厂修边后的封面和封底的尺寸。我的书的书脊大小是 0.411&quot;，出血量是 0.125&quot;。也就是说，书脊的左上角 X、Y 的正确位置是：</p><ul><li>X 位置（出血量+裁剪宽度）：0.411+7.44=7.8510&quot;</li><li>Y 位置（减去出血量）：-0.125&quot;</li></ul><p>矩形的尺寸是我的书封面的全高（包括出血）和 PDF 模板中标明的书脊宽度。</p><ul><li>宽度：0.411&quot;</li><li>高度：9.93&quot;</li></ul><p>将矩形的<ruby>填充<rt>Fill</rt></ruby>设置为你喜欢的颜色，将<ruby>笔触<rt>Stroke</rt></ruby>设置为<ruby>无<rt>None</rt></ruby>以隐藏边界。如果你正确地定义了 Scribus 文档，你应该最终得到一个矩形，它可以延伸到位于文档中心的图书封面的顶部和底部边缘。</p><p><img src="https://opensource.com/sites/default/files/uploads/scribus-spine-rectangle.jpg" alt="Book spine in Scribus" title="Book spine in Scribus"></p><p>如果矩形与文档不完全匹配，可能是你在创建 Scribus 文档时设置了错误的尺寸。由于你还没有在书的封面上花太多精力，所以可能最容易的做法是重新开始，而不是尝试修复你的错误。</p><h3 id="剩下的就看你自己了" tabindex="-1">剩下的就看你自己了 <a class="header-anchor" href="#剩下的就看你自己了" aria-label="Permalink to “剩下的就看你自己了”">​</a></h3><p>接下来，你可以创建你的书的封面的其余部分。始终使用 PDF 模板作为指导。封底在左边，封面在右边</p><p>我可以做一个简单的书籍封面，但我缺乏艺术能力，无法创造出真正醒目的设计。在自己设计了几个书的封面后，我对那些能设计出好封面的人产生了敬意。但如果你只是需要制作一个简单的封面，你可以通过开源软件自己动手。</p><hr>',32)),e("p",null,[t[9]||(t[9]=r("via: ",-1)),s(u,{href:"https://opensource.com/article/20/9/open-source-publishing-scribus"},{default:i(()=>[...t[8]||(t[8]=[r("https://opensource.com/article/20/9/open-source-publishing-scribus",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=r("作者：",-1)),s(u,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...t[10]||(t[10]=[r("Jim Hall",-1)])]),_:1}),t[15]||(t[15]=r(" 选题：",-1)),s(u,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[11]||(t[11]=[r("lujun9972",-1)])]),_:1}),t[16]||(t[16]=r(" 译者：",-1)),s(u,{href:"https://github.com/geekpi"},{default:i(()=>[...t[12]||(t[12]=[r("geekpi",-1)])]),_:1}),t[17]||(t[17]=r(" 校对：",-1)),s(u,{href:"https://github.com/wxy"},{default:i(()=>[...t[13]||(t[13]=[r("wxy",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=r("本文由 ",-1)),s(u,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[18]||(t[18]=[r("LCTT",-1)])]),_:1}),t[21]||(t[21]=r(" 原创编译，",-1)),s(u,{href:"https://linux.cn/"},{default:i(()=>[...t[19]||(t[19]=[r("Linux中国",-1)])]),_:1}),t[22]||(t[22]=r(" 荣誉推出",-1))])])}const x=l(b,[["render",d]]);export{T as __pageData,x as default};
